// Forgotten Sands Recompiled - host graphics and Xbox 360 D3D replacement.
//
// Ported from UnleashedRecomp's gpu/video.cpp (plume on Vulkan, bindless textures, XenosRecomp
// shaders reading constants through buffer device addresses) and adapted to Torchlight:
//  * Torchlight's D3D is the stock Xbox 360 D3D library statically linked next to Ogre3D; the
//    hooked addresses are listed at the end of this file (see work/d3d_research/d3d_functions.md).
//  * The guest device is 0x5F80 bytes; offsets past 0x2800 differ from Sonic's (DEV_* below).
//  * Render-state setters are called through the device table AND directly by Ogre, so every
//    setter function is hooked by address: the original guest setter still runs (it keeps the
//    guest's shadow registers, which the guest getters read) and the value is recorded host side.
//  * Shaders: every CreateVertexShader/CreatePixelShader microcode blob (the 18 precompiled
//    shaders.fxobj ones and the Ogre RTSS shaders the guest HLSL compiler produces at runtime)
//    goes through XenosRecomp + DXC in-process, cached on disk by hash (user/shader_cache).
//  * Rendering is recorded synchronously on the calling guest thread (one global lock) instead
//    of Unleashed's render thread; simpler while bringing the game up.
#include <kernel/achievements.h>
#ifdef _WIN32
#include "achievement_toast.h"
#endif
