// the sun is visible with an occlusion query (a depth-tested draw with no colour target between
// D3DQuery_Issue(BEGIN) and Issue(END)) and scales the glow by the pixel count it gets back a few frames later.
// The queries used to answer "100000 pixels" always. Now every draw of the main device inside such a bracket
// runs inside a real GPU occlusion query; the counts are read back when the same group of query slots comes
// round again (4 frames later, the command list that held them has long finished), divided by the render scale
// (the game expects 1280x720 pixel counts) and handed out by D3DQuery_GetData. A query that was never measured
// still answers 100000 - and so does every query whose bracket held no draw of the main device: the game also
// culls scenery with hundreds of queries whose draws we do not see inside the bracket (first try: they all
// came back 0 and the towers and domes of the level start vanished). Only measured queries get real answers. FS_NO_OCCLUSION=1: the old answer. FS_LOG_OCCLUSION=1: logs the results.
