struct DescriptorAllocator
{
    uint32_t capacity = TEXTURE_DESCRIPTOR_NULL_COUNT;
    std::vector<uint32_t> freed;

    uint32_t allocate()
    {
        if (!freed.empty()) { uint32_t v = freed.back(); freed.pop_back(); return v; }
        return capacity++;
    }
    void free(uint32_t v) { if (v >= TEXTURE_DESCRIPTOR_NULL_COUNT) freed.push_back(v); }
};
