// ---------------------------------------------------------------------------------------------
// Per-frame upload memory

struct UploadAllocation
{
    const RenderBuffer* buffer;
    uint64_t offset;
    uint8_t* memory;
    uint64_t deviceAddress;
};

struct UploadAllocator
{
    static constexpr size_t SIZE = 16 * 1024 * 1024;

    struct Chunk { std::unique_ptr<RenderBuffer> buffer; uint8_t* memory = nullptr; uint64_t deviceAddress = 0; };
    std::vector<Chunk> chunks;
    std::vector<std::unique_ptr<RenderBuffer>> dedicated;
    uint32_t index = 0;
    uint32_t offset = 0;

    UploadAllocation allocate(uint32_t size, uint32_t alignment)
    {
        if (size > SIZE / 2)
        {
            auto& buffer = dedicated.emplace_back(g_device->createBuffer(RenderBufferDesc::UploadBuffer(size, RenderBufferFlag::CONSTANT | RenderBufferFlag::VERTEX | RenderBufferFlag::INDEX)));
            auto memory = reinterpret_cast<uint8_t*>(buffer->map());
            return { buffer.get(), 0, memory, buffer->getDeviceAddress() };
        }

        offset = AlignUp(offset, alignment);
        if (offset + size > SIZE)
        {
            ++index;
            offset = 0;
        }
        if (chunks.size() <= index)
            chunks.resize(index + 1);

        auto& chunk = chunks[index];
        if (chunk.buffer == nullptr)
        {
            chunk.buffer = g_device->createBuffer(RenderBufferDesc::UploadBuffer(SIZE, RenderBufferFlag::CONSTANT | RenderBufferFlag::VERTEX | RenderBufferFlag::INDEX));
            chunk.memory = reinterpret_cast<uint8_t*>(chunk.buffer->map());
            chunk.deviceAddress = chunk.buffer->getDeviceAddress();
        }

        UploadAllocation result{ chunk.buffer.get(), offset, chunk.memory + offset, chunk.deviceAddress + offset };
        offset += size;
        return result;
    }

    void reset()
    {
        index = 0;
        offset = 0;
        dedicated.clear();
    }
};
static UploadAllocator g_uploadAllocators[NUM_FRAMES];

