// Internal resolution scale (Step 29): screen-sized render targets (the 1280x720 family: 1280x720, the
// 1280x384 tiles, 640x360 ... 80x45) and the textures they are resolved into are made scale times larger,
// with viewports, scissors, clear and resolve rectangles scaled to match. 1 = the console's 720p.
static Scale2 g_resScale;
static int32_t ScaleI(int32_t v, float s) { return int32_t(std::lround(double(v) * s)); }
static RenderRect ScaleRect(const RenderRect& r, const Scale2& s) { return RenderRect(ScaleI(r.left, s.x), ScaleI(r.top, s.y), ScaleI(r.right, s.x), ScaleI(r.bottom, s.y)); }

// ---------------------------------------------------------------------------------------------
// Layout tracking

static ankerl::unordered_dense::map<const RenderTexture*, RenderTextureLayout> g_layouts;

static void Transition(const RenderTexture* texture, RenderTextureLayout layout)
{
    if (texture == nullptr)
        return;
    auto& current = g_layouts[texture];
    if (current != layout)
    {
        current = layout;
        g_commandLists[g_frame]->barriers(RenderBarrierStage::GRAPHICS | RenderBarrierStage::COPY, RenderTextureBarrier(const_cast<RenderTexture*>(texture), layout));
    }
}

