static uint32_t g_renderStates[RS_COUNT]; // main device
// Forgotten Sands records on several devices at once: each device keeps its own render states (a new device
// starts from the main device's current ones).
static std::unordered_map<uint32_t, std::array<uint32_t, RS_COUNT>> g_deviceRenderStates;
// Step 35 (lock contention): recording devices' render states also live in fixed slots, so a job thread can
// set its own device's states without taking g_mutex (slots are only added under g_mutex, never removed).
struct DeviceRsSlot { std::atomic<uint32_t> dev{0}; uint32_t* rs = nullptr; };
static DeviceRsSlot g_deviceRsSlots[32];
static thread_local std::atomic<bool> g_pendingUpFlag{false}; // mirror of this thread's g_pendingUp.pending (Step 35: per thread)
static uint32_t* FindDeviceRsLockFree(uint32_t dev)
{
    for (auto& slot : g_deviceRsSlots)
    {
        const uint32_t d = slot.dev.load(std::memory_order_acquire);
        if (d == dev) return slot.rs;
        if (d == 0) return nullptr;
    }
    return nullptr;
}
static uint8_t* g_guestDevice;          // host pointer to the guest device
static uint32_t g_guestDeviceAddress;

struct DeviceScope
{
    uint8_t* saved;
    explicit DeviceScope(uint32_t dev) : saved(g_guestDevice)
    {
        if (dev != 0 && dev != g_guestDeviceAddress)
            g_guestDevice = G2H(dev);
    }
    ~DeviceScope() { g_guestDevice = saved; }
};

static thread_local uint32_t g_replayOrigin = 0; // device a replayed snapshot came from (see DeferDraw)
static bool g_replaySpareIb = false;             // the replayed draw's index buffer is the spare one holding its captured copy
static thread_local uint32_t* g_replayRenderStates = nullptr; // render states captured with a deferred draw (see DeferDraw)
static uint32_t* RenderStatesFor(uint32_t dev)
{
    if (g_replayRenderStates != nullptr)
        return g_replayRenderStates;
    if (g_replayOrigin != 0)
        dev = g_replayOrigin;
    if (dev == 0 || dev == g_guestDeviceAddress)
        return g_renderStates;
    auto [it, inserted] = g_deviceRenderStates.try_emplace(dev);
    if (inserted)
    {
        std::copy(std::begin(g_renderStates), std::end(g_renderStates), it->second.begin());
        for (auto& slot : g_deviceRsSlots)
            if (slot.dev.load() == 0) { slot.rs = it->second.data(); slot.dev.store(dev, std::memory_order_release); break; }
    }
    return it->second.data();
}
