// sub_821AFC80: CreateTexture(Width, Height, Depth, Levels, Usage, Format, Pool, Type) -> texture
PPC_FUNC(sub_FS_GUEST_OWNS_821AFC80)
{
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    uint32_t w = ctx.r3.u32, h = ctx.r4.u32, d = ctx.r5.u32, levels = ctx.r6.u32, usage = ctx.r7.u32, format = ctx.r8.u32, type = ctx.r10.u32;
    auto texture = CreateHostTexture(w, h, d, levels, format, type, true);
    LOG_FIRST(60, "[gpu] CreateTexture {}x{}x{} levels {} usage 0x{:X} format 0x{:08X} type {} -> 0x{:08X}", w, h, d, levels, usage, format, type, H2G(texture));
    ctx.r3.u64 = H2G(texture);
}

// sub_821AFDA0: CreateSurface(Width, Height, Format, MultiSample, pParameters) -> surface (render target or depth)
PPC_FUNC(sub_FS_GUEST_OWNS_821AFDA0)
{
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    auto surface = CreateHostSurface(ctx.r3.u32, ctx.r4.u32, ctx.r5.u32);
    LOG_FIRST(30, "[gpu] CreateSurface {}x{} format 0x{:08X} ms {} -> 0x{:08X}{}", ctx.r3.u32, ctx.r4.u32, ctx.r5.u32, ctx.r6.u32, H2G(surface), surface->isDepth ? " (depth)" : "");
    ctx.r3.u64 = H2G(surface);
}

static uint32_t CreateBuffer(ResourceType type, uint32_t length, uint32_t format)
{
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    auto buffer = g_userHeap.AllocPhysical<GuestBuffer>(type);
    buffer->dataSize = std::max(length, 4u);
    buffer->guestFormat = format;
    buffer->indexFormat = (format == 6) ? RenderFormat::R32_UINT : RenderFormat::R16_UINT; // D3DFMT_INDEX32 = 6
    buffer->buffer = g_device->createBuffer(RenderBufferDesc::VertexBuffer(AlignUp(buffer->dataSize, 4), RenderHeapType::DEFAULT, RenderBufferFlag::INDEX));
    buffer->hostSize = AlignUp(buffer->dataSize, 4);
    buffer->mappedMemory = reinterpret_cast<uint8_t*>(g_userHeap.AllocPhysical(buffer->dataSize, 0x10));
    memset(buffer->mappedMemory, 0, buffer->dataSize);
    g_stats.buffers++;
    return H2G(buffer);
}

