// sub_821A58A8: resource destroy
// The game's own destroy frees its headers/memory; ours (RESOURCE_MAGIC) are freed by DestructResource.
PPC_FUNC_IMPL(__imp__sub_821A58A8);
PPC_FUNC(sub_821A58A8)
{
    auto r = G2H<GuestResource>(ctx.r3.u32);
    if (r && r->magic == RESOURCE_MAGIC)
    {
        DestructResource(ctx.r3.u32);
        return;
    }
    {
        std::lock_guard lock(g_mutex); FlushPendingVertices();
        DropShadow(ctx.r3.u32);
    }
    __imp__sub_821A58A8(ctx, base);
}

