// =============================================================================================
// Hooks: state
// =============================================================================================

static void SetDefaultViewport(GuestSurface* surface)
{
    if (surface == nullptr)
        return;
    g_viewport = RenderViewport(0, 0, float(surface->width), float(surface->height), 0, 1);
    uint8_t* dev = g_guestDevice;
    if (dev)
    {
        DevF32(dev, DEV_VIEWPORT + 0) = 0.0f; DevF32(dev, DEV_VIEWPORT + 4) = 0.0f;
        DevF32(dev, DEV_VIEWPORT + 8) = float(surface->width); DevF32(dev, DEV_VIEWPORT + 12) = float(surface->height);
        DevF32(dev, DEV_VIEWPORT + 16) = 0.0f; DevF32(dev, DEV_VIEWPORT + 20) = 1.0f;
    }
}

// Xbox Resolve copies whatever is in EDRAM, so games may unbind the render target before resolving: the
// last bound color / depth surfaces stand in for "what EDRAM holds".

static void SetRenderTargetInternal(uint32_t index, GuestSurface* surface)
{
    if (index == 0 && surface)
        g_lastRenderTarget = surface;
    if (g_guestDevice)
        DevU32(g_guestDevice, DEV_RT + index * 4) = GuestAddr(surface);
    if (index != 0)
    {
        if (surface) WARN_ONCE("[gpu] multiple render targets (index {}) not supported", index);
        return;
    }
    g_renderTarget = surface;
    g_currentFramebuffer = nullptr;
    SetDefaultViewport(surface);
}

static void SetDepthStencilInternal(GuestSurface* surface)
{
    if (g_guestDevice)
        DevU32(g_guestDevice, DEV_DS) = GuestAddr(surface);
    g_depthStencil = surface;
    if (surface)
        g_lastDepthStencil = surface;
    g_currentFramebuffer = nullptr;
}

// Forgotten Sands also changes render targets by writing DEV_RT[0] / DEV_DS itself (not through
// SetRenderTarget): follow the device fields before draws, clears and resolves.
static void SyncTargetsFromDevice()
{
    if (!g_guestDevice)
        return;
    const uint32_t rt = DevU32(g_guestDevice, DEV_RT);
    uint32_t ds = DevU32(g_guestDevice, DEV_DS);
    if (g_oqActive && ds && g_oqSceneDepth && H2G(g_guestDevice) == g_guestDeviceAddress && ds != GuestAddr(g_oqSceneDepth))
    {
        auto own = AsResource<GuestSurface>(ds, ResourceType::Surface);
        if (own && own->isDepth && own->width == g_oqSceneDepth->width && own->height == g_oqSceneDepth->height)
        {
            LOG_FIRST(3, "[gpu] occlusion query: depth surface 0x{:08X} replaced by the scene depth 0x{:08X} ({}x{})", ds, GuestAddr(g_oqSceneDepth), own->width, own->height);
            ds = GuestAddr(g_oqSceneDepth);
        }
        else
            LOG_FIRST(6, "[gpu] occlusion query: depth surface 0x{:08X} ({}x{}) does not match the scene depth 0x{:08X} ({}x{})", ds, own ? own->width : 0, own ? own->height : 0, GuestAddr(g_oqSceneDepth), g_oqSceneDepth->width, g_oqSceneDepth->height);
    }
    if (rt != GuestAddr(g_renderTarget))
    {
        g_renderTarget = rt ? AsResource<GuestSurface>(rt, ResourceType::Surface) : nullptr;
        g_currentFramebuffer = nullptr;
        // (no default viewport here: the device's own viewport fields are read at draw time)
    }
    if (ds != GuestAddr(g_depthStencil))
    {
        auto surface = ds ? AsResource<GuestSurface>(ds, ResourceType::Surface) : nullptr;
        g_depthStencil = surface && surface->isDepth ? surface : nullptr;
        g_currentFramebuffer = nullptr;
    }
}

// sub_821AB5A8: SetRenderTarget(dev, index, surface). The game's own one runs first (device state and
// PM4 into the scratch buffer), then the host mirrors it.
PPC_FUNC_IMPL(__imp__sub_821AB5A8);
PPC_FUNC(sub_821AB5A8)
{
    { std::lock_guard lock(g_mutex); FlushPendingVertices(); } // a pending BeginVertices draw uses the state before this call
    {
        PPCContext saved = ctx;
        __imp__sub_821AB5A8(ctx, base);
        ctx.r4 = saved.r4; ctx.r5 = saved.r5;
    }
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    auto surface = AsResource<GuestSurface>(ctx.r5.u32, ResourceType::Surface);
    if (ctx.r5.u32 && surface == nullptr)
        LOG_FIRST(10, "[gpu] SetRenderTarget with unknown surface 0x{:08X}", ctx.r5.u32);
    if (surface && surface->parentTexture)
    {
        WARN_ONCE("[gpu] SetRenderTarget on a texture level surface is not supported");
        surface = nullptr;
    }
    if (ctx.r3.u32 == g_guestDeviceAddress) // other devices: their own fields were set by the game's function
        SetRenderTargetInternal(ctx.r4.u32, surface);
}

// sub_821AB8F8: SetDepthStencilSurface(dev, surface) - the game's own one runs first.
PPC_FUNC_IMPL(__imp__sub_821AB8F8);
PPC_FUNC(sub_821AB8F8)
{
    { std::lock_guard lock(g_mutex); FlushPendingVertices(); } // a pending BeginVertices draw uses the state before this call
    {
        PPCContext saved = ctx;
        __imp__sub_821AB8F8(ctx, base);
        ctx.r4 = saved.r4;
    }
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    auto surface = AsResource<GuestSurface>(ctx.r4.u32, ResourceType::Surface);
    if (ctx.r3.u32 == g_guestDeviceAddress)
        SetDepthStencilInternal(surface && surface->isDepth ? surface : nullptr);
}

// sub_821C3918: ClearF(dev, Flags, pRect, pColor (float4), Z, Stencil)
static void ClearInternal(uint32_t flags, const RenderRect* rect, const float* color, float z, uint32_t stencil)
{
    SyncTargetsFromDevice();
    g_stats.clears++;
    LOG_FIRST(12, "[gpu] clear flags 0x{:X} z {} rt {}x{} ds {}", flags, z, g_renderTarget ? g_renderTarget->width : 0, g_renderTarget ? g_renderTarget->height : 0, g_depthStencil ? 1 : 0);
    if (g_traceFrame) TraceEvent(fmt::format("clear dev 0x{:08X} flags 0x{:X} rt 0x{:08X} ds 0x{:08X} color {:.2f} z {:.3f}{}", g_replayOrigin ? g_replayOrigin : H2G(g_guestDevice), flags, GuestAddr(g_renderTarget), GuestAddr(g_depthStencil), color ? color[0] : -1.0f, z, g_replayOrigin ? " (replayed)" : ""));
    auto& commandList = g_commandLists[g_frame];
    bool clearColor = (flags & 0xF) != 0 && g_renderTarget != nullptr && color != nullptr;
    bool clearDepth = (flags & 0x30) != 0 && g_depthStencil != nullptr;

    // Internal resolution: clear rectangles are in the console's pixels.
    RenderRect scaledRect;
    auto scaled = [&](GuestSurface* target) -> const RenderRect*
    {
        if (rect == nullptr || target == nullptr || target->scale.IsOne())
            return rect;
        scaledRect = ScaleRect(*rect, target->scale);
        return &scaledRect;
    };
    // Step 37 (the tester, Odin: sunlight flashing where the tower's shadow should be - the sun's shadow maps had a
    // checkerboard of holes in those frames): a whole-target clear used to be a clear command in a render pass of
    // its own (colour-only / depth-only framebuffer), and the draws came in later passes that load the target. The
    // Odin's GPU (a tile renderer) lost blocks of the first draws after such a clear. Now the clear is the load
    // operation of the render pass the following draws go into (colour and depth as they are bound), which is how
    // tile renderers want it - and it saves loading the old contents. Measured on the Odin: NOT better than the old
    // way (so it is opt-in, FS_PASS_CLEAR=1); what helps is repeating the clear command right before the first draw
    // (ReclearDepthBeforeDraw: holes ~50x rarer) and not interrupting the pass after it (DirectOnDemand).
    {
        static const bool s_passClear = getenv("FS_PASS_CLEAR") != nullptr; // opt-in: on the Odin it was no better (holes in 4 of 8 runs, up to 57 of 150 frames)
        if (s_passClear && rect == nullptr && (clearColor || clearDepth) && (!clearColor || (flags & 0xF) == 0xF))
        {
            GuestSurface* rt = g_renderTarget;
            GuestSurface* ds = g_depthStencil;
            const bool dsFits = ds != nullptr && !(rt != nullptr && (ds->hostWidth < rt->hostWidth || ds->hostHeight < rt->hostHeight));
            if ((!clearDepth || dsFits) && SetFramebufferForDraw(rt != nullptr, ds != nullptr, true))
            {
                const RenderColor c = clearColor ? RenderColor(color[0], color[1], color[2], color[3]) : RenderColor();
                if (commandList->beginFramebufferWithClear(clearColor ? &c : nullptr, clearDepth && (flags & 0x10) != 0, clearDepth && (flags & 0x20) != 0, z, stencil & 0xFF))
                {
                    if (clearColor && g_colorReclear.surface == rt) g_colorReclear.surface = nullptr;
                    if (clearDepth && g_depthReclear.surface == ds) g_depthReclear.surface = nullptr;
                    static std::atomic<uint64_t> s_n{0};
                    if (s_n++ == 0) LOGFN("[gpu] whole-target clears start their render pass (load operation clear)");
                    return;
                }
            }
        }
    }
    if (clearColor)
    {
        if (SetFramebufferForDraw(true, false, true))
        {
            const RenderRect* r = scaled(g_renderTarget);
            commandList->clearColor(0, RenderColor(color[0], color[1], color[2], color[3]), r, r ? 1 : 0);
            // Step 37: remembered for the first draw into this target (see ReclearDepthBeforeDraw).
            if (r == nullptr && (flags & 0xF) == 0xF) { g_colorReclear.surface = g_renderTarget; for (int i = 0; i < 4; i++) g_colorReclear.color[i] = color[i]; }
            else if (g_colorReclear.surface == g_renderTarget) g_colorReclear.surface = nullptr; // a partial / masked clear came after it
        }
    }
    if (clearDepth)
    {
        if (SetFramebufferForDraw(false, true, true))
        {
            const RenderRect* r = scaled(g_depthStencil);
            commandList->clearDepthStencil((flags & 0x10) != 0, (flags & 0x20) != 0, z, stencil & 0xFF, r, r ? 1 : 0);
            // Step 37: remembered for the first draw that uses this depth buffer (see PrepareDraw).
            if (r == nullptr && (flags & 0x10) != 0) g_depthReclear = { g_depthStencil, z, stencil & 0xFF, (flags & 0x20) != 0 };
            else if (g_depthReclear.surface == g_depthStencil) g_depthReclear.surface = nullptr; // a partial clear came after it
        }
    }
}

static bool DeferClear(uint32_t dev, uint32_t flags, const RenderRect* rect, const float* color, float z, uint32_t stencil);
PPC_FUNC(sub_821C3918)
{
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    DeviceScope deviceScope(ctx.r3.u32); // clears recorded on the other devices clear their targets
    float color[4] = { 0, 0, 0, 0 };
    if (auto c = G2H<be<float>>(ctx.r6.u32))
        for (int i = 0; i < 4; i++) color[i] = c[i];
    RenderRect rect;
    const RenderRect* pRect = nullptr;
    if (auto r = G2H<be<int32_t>>(ctx.r5.u32))
    {
        rect = RenderRect(r[0], r[1], r[2], r[3]);
        pRect = &rect;
    }
    if (DeferClear(ctx.r3.u32, ctx.r4.u32, pRect, ctx.r6.u32 ? color : nullptr, float(ctx.f1.f64), ctx.r8.u32))
        return;
    ClearInternal(ctx.r4.u32, pRect, ctx.r6.u32 ? color : nullptr, float(ctx.f1.f64), ctx.r8.u32);
}

// sub_821A8D20: SetViewportF internal (dev, x, y, w, h, minZ, maxZ, flags)
PPC_FUNC(sub_821A8D20)
{
    std::lock_guard lock(g_mutex); FlushPendingVertices();
    float x = float(ctx.f1.f64), y = float(ctx.f2.f64), w = float(ctx.f3.f64), h = float(ctx.f4.f64);
    float minZ = float(ctx.f5.f64), maxZ = float(ctx.f6.f64);
    g_viewport = RenderViewport(x, y, w, h, minZ, maxZ);
    uint8_t* dev = G2H(ctx.r3.u32);
    DevF32(dev, DEV_VIEWPORT + 0) = x; DevF32(dev, DEV_VIEWPORT + 4) = y; DevF32(dev, DEV_VIEWPORT + 8) = w;
    DevF32(dev, DEV_VIEWPORT + 12) = h; DevF32(dev, DEV_VIEWPORT + 16) = minZ; DevF32(dev, DEV_VIEWPORT + 20) = maxZ;
    DevU32(dev, DEV_VIEWPORT + 24) = ctx.r10.u32;
}

