// =============================================================================================
// Hooks: draws
// =============================================================================================


// =============================================================================================
// Forgotten Sands: draws recorded into D3D command buffers on the other devices are kept (with a copy of
// the device state) and replayed in EndCommandBuffer order right before the main device resolves a
// target they draw into, or at the end of the frame. Drawing them at record time put parallel jobs out of
// order (e.g. all shadow cascades before the first cascade's resolve). FS_NO_DEFER=1 turns this off.
// =============================================================================================
static constexpr uint32_t DEFER_SNAPSHOT_SIZE = 0x4000;   // device fields used by PrepareDraw
static constexpr uint32_t DEFER_POOL_SIZE = 256 * 1024 * 1024; // 0xE1000000-0xF1000000 (level: ~16 MB per frame)
struct DeferredCapture { uint32_t header, data; uint64_t hash; uint32_t size; uint32_t kind; }; // kind: 0 vertex, 1 index 16 bit, 2 index 32 bit
// Fixed-capacity vector (Step 35: a deferred draw allocated two std::vectors - ~3% of the render thread in new/free).
template<typename T, size_t N> struct InlineVec
{
    T items[N]; uint32_t count = 0;
    void push_back(const T& v) { if (count < N) items[count++] = v; }
    T* begin() { return items; } T* end() { return items + count; }
    const T* begin() const { return items; } const T* end() const { return items + count; }
    bool empty() const { return count == 0; } size_t size() const { return count; }
    T* data() { return items; }
    void assign(const T* a, const T* b) { count = 0; for (; a != b && count < N; ++a) items[count++] = *a; }
};
struct DeferredDraw { uint32_t kind, a, b, c; int32_t d; uint32_t snapshot, origin, data, dataSize; float clear[5]; int32_t rect[4]; InlineVec<DeferredCapture, 17> captures; InlineVec<uint32_t, 0x65> renderStates; uint64_t frame = 0; uint64_t poolMark = 0; };
struct PendingCommandBuffer { std::vector<DeferredDraw> draws; std::set<uint32_t> targets; bool ended = false; uint32_t cbObject = 0; uint32_t device = 0; std::thread::id thread; };
static std::unordered_map<uint32_t, PendingCommandBuffer*> g_recordingCbs;    // cb object -> open recording
static std::deque<PendingCommandBuffer*> g_endedCbs;                          // in EndCommandBuffer order
static constexpr uint32_t DEFER_POOL_BASE = 0xE1000000; // unused guest range (not the game's heaps; 0xE0000000 view is not aliased here)
static std::atomic<uint32_t> g_deferPoolOffset{0};
static std::atomic<uint64_t> g_deferPoolTotal{0};
static uint64_t g_poolOverwrites = 0; // bytes ever allocated (diag: has the ring overwritten a pending draw?)
// Step 35 (60 fps): the job threads record into g_recordingCbs / g_endedCbs / the defer pool under this lock
// only, not g_mutex, so recording no longer waits for the render thread (and the other way round).
// Lock order: g_mutex before g_recordMutex, never the reverse.
static std::mutex g_recordMutex;
static std::condition_variable g_recordCv; // notified when a command buffer recording ends (render thread waits on it)
struct CaptureCacheEntry { uint32_t data = 0, size = 0, copy = 0; uint64_t hash = 0; uint32_t rangeKey[32] = {}, rangeLo[32] = {}, rangeHi[32] = {}; uint32_t rangeNext = 0; uint32_t sameRun = 0, uses = 0; uint64_t poolMark = 0; uint32_t armSerial = 0, dirtyHits = 0; };

// Compares 8 blocks of 64 bytes spread over [p, p + n) (n > 1024).
static std::atomic<uint64_t> g_capCmp[5]; // stats: young full, periodic full, sampled, small, bytes fully compared
static bool SampledEqual(const uint8_t* a, const uint8_t* b, uint32_t n)
{
    for (uint32_t k = 0; k < 8; k++)
    {
        const uint32_t off = uint32_t(uint64_t(n - 64) * k / 7);
        if (memcmp(a + off, b + off, 64) != 0)
            return false;
    }
    return true;
}
// Buffer header -> last copy, shared by all recording threads (a per-thread cache made 5x the copies and the
// defer pool ring overwrote draws still waiting for replay - crash at the loading screen). Sharded locks.
struct CaptureShard { std::mutex m; std::unordered_map<uint32_t, CaptureCacheEntry> map; };
static CaptureShard g_captureShards[64];

static uint32_t DeferAlloc(uint32_t size)
{
    size = AlignUp(size, 16);
    uint32_t o = g_deferPoolOffset.load(std::memory_order_relaxed);
    for (;;)
    {
        uint32_t start = o, next = o + size;
        if (next > DEFER_POOL_SIZE) { start = 0; next = size; } // ring: the oldest frame's data is long replayed
        if (g_deferPoolOffset.compare_exchange_weak(o, next, std::memory_order_relaxed))
        {
            g_deferPoolTotal.fetch_add(next - start + (start == 0 && o != 0 ? DEFER_POOL_SIZE - o : 0), std::memory_order_relaxed);
            return DEFER_POOL_BASE + start;
        }
    }
}

static bool DeferDraw(uint32_t dev, uint32_t kind, uint32_t a, uint32_t b, uint32_t c, int32_t d, uint32_t dataGuest, uint32_t dataSize)
{
    static const bool s_disabled = getenv("FS_NO_DEFER") != nullptr;
    if (s_disabled || dev == 0 || dev == g_guestDeviceAddress || g_replayOrigin != 0)
        return false;
    const uint32_t cb = DevU32(G2H(dev), 13724);
    if (cb == 0)
        return false;
    DeferredDraw dd{ kind, a, b, c, d, DeferAlloc(DEFER_SNAPSHOT_SIZE), dev, 0, dataSize, {}, {} };
    dd.poolMark = g_deferPoolTotal.load();
    memcpy(G2H(dd.snapshot), G2H(dev), DEFER_SNAPSHOT_SIZE);
    if (dataGuest && dataSize)
    {
        dd.data = DeferAlloc(dataSize);
        memcpy(G2H(dd.data), G2H(dataGuest), dataSize);
    }
    // Dynamic vertex/index buffers are rewritten by the game for later draws (and later frames) before the
    // command buffer is replayed: keep a copy of their contents as they are now (white debris shards and
    // blinking rubble on the bridge floor - the tester). FS_NO_DEFER_CAPTURE=1: off.
    static const bool s_noCapture = getenv("FS_NO_DEFER_CAPTURE") != nullptr;
    if (!s_noCapture)
    {
        // Only the bytes this draw reads decide whether the last copy can be reused (comparing or hashing whole
        // buffers for every draw made 4K frames 2x slower).
        // Buffers are found from their game header (not the render thread's shadow table, which this thread must
        // not touch without g_mutex): VB +0x18 = data | type, +0x1C = size in dwords << 2; IB +0x18 data, +0x1C size.
        auto bufferOf = [](uint32_t header, bool index, uint32_t& data, uint32_t& size, bool& index32)
        {
            auto w = G2H<be<uint32_t>>(header);
            if (index) { data = w[6]; size = w[7]; index32 = (uint32_t(w[0]) & 0x80000000) != 0; }
            else { data = uint32_t(w[6]) & 0xFFFFFFFC; size = ((uint32_t(w[7]) >> 2) & 0xFFFFFF) * 4; index32 = false; }
            return data != 0 && size != 0 && size <= g_dynamicLimit;
        };
        // The last capture's cache entry (for the index range cache below). Entries are never erased, so the
        // pointer stays valid; its fields are only touched under the shard lock.
        CaptureCacheEntry* lastEntry = nullptr;
        uint32_t lastCopy = 0;
        auto capture = [&](uint32_t header, bool index, uint32_t rangeOff, uint32_t rangeSize)
        {
            lastEntry = nullptr;
            lastCopy = 0;
            if (header == 0) return;
            uint32_t data, size; bool i32;
            if (!bufferOf(header, index, data, size, i32)) return;
            if (rangeOff >= size) rangeOff = 0, rangeSize = size;
            rangeSize = std::min(rangeSize, size - rangeOff);
            auto& shard = g_captureShards[(header >> 4) & 63];
            std::lock_guard shardLock(shard.m);
            auto& e = shard.map[header];
            // A copy older than half the defer pool ring may be overwritten soon: it is renewed (below) but still
            // counts as matching, so a static buffer keeps its "stable" run. Older than 3/4: not trusted at all.
            const uint64_t age = g_deferPoolTotal.load(std::memory_order_relaxed) - e.poolMark;
            bool same = e.copy != 0 && e.data == data && e.size == size && age < DEFER_POOL_SIZE / 4 * 3;
            if (same)
            {
                // Buffers that matched 16 times in a row (static meshes) are compared on 8 sampled blocks, fully
                // every 32nd use (comparing every draw's whole range cost ~5% of the render thread, Step 35).
                // FS_FULL_CAPTURE_CMP=1: always compare everything.
                static const bool s_fullCmp = getenv("FS_SAMPLED_CAPTURE_CMP") == nullptr; // sampled compares missed partial rewrites (floor debris blinked)
                const uint8_t* live = G2H<uint8_t>(data) + rangeOff;
                const uint8_t* copy = G2H<uint8_t>(e.copy) + rangeOff;
                if (e.armSerial != 0 && WriteWatch::IsClean(data, size, e.armSerial) /* whole buffer: the computed draw range can miss what the shader really fetches */)
                {
                    WriteWatch::g_clean.fetch_add(1, std::memory_order_relaxed);
                    same = true;
                    // FS_VERIFY_WATCH=1 (test): also compare, and report a clean buffer whose bytes changed.
                    static const bool s_verify = getenv("FS_VERIFY_WATCH") != nullptr;
                    if (s_verify && memcmp(live, copy, rangeSize) != 0)
                    {
                        static std::atomic<uint64_t> s_miss{0};
                        uint32_t at = 0; while (at < rangeSize && live[at] == copy[at]) at++;
                        if (s_miss.fetch_add(1) < 30)
                            LOGFN("[watch] MISSED change: header 0x{:08X} data 0x{:08X} size 0x{:X} range +0x{:X}/0x{:X} first diff at 0x{:08X} (page armed {} last write {} serial {})",
                                header, data, size, rangeOff, rangeSize, data + rangeOff + at, uint32_t(WriteWatch::g_armed[WriteWatch::Canon(data + rangeOff + at) >> 12].load()),
                                WriteWatch::g_lastWrite[WriteWatch::Canon(data + rangeOff + at) >> 12].load(), e.armSerial);
                    }
                }
                else if (!s_fullCmp && e.sameRun >= 16 && (++e.uses & 31) != 0 && rangeSize > 1024)
                {
                    g_capCmp[2].fetch_add(1, std::memory_order_relaxed);
                    same = SampledEqual(live, copy, rangeSize);
                }
                else
                {
                    g_capCmp[rangeSize <= 1024 ? 3 : e.sameRun < 16 ? 0 : 1].fetch_add(1, std::memory_order_relaxed);
                    g_capCmp[4].fetch_add(rangeSize, std::memory_order_relaxed);
                    same = memcmp(live, copy, rangeSize) == 0;
                    if (same && e.armSerial != 0) e.dirtyHits++; // written but equal: renew (and re-arm) after a few
                }
            }
            // Stable (16 matches in a row): take a fresh copy under a write watch once, then reuse it.
            const bool wantArm = WriteWatch::Enabled() && size >= 2048;
            const bool rearm = same && wantArm && ((e.armSerial == 0 && e.sameRun + 1 >= 16) || e.dirtyHits > 8);
            if (same && age < DEFER_POOL_SIZE / 2 && !rearm)
                e.sameRun++;
            else
            {
                e.sameRun = same ? e.sameRun + 1 : 0;
                e.dirtyHits = 0;
                e.armSerial = (wantArm && e.sameRun >= 16) ? WriteWatch::Arm(data, size) : 0; // before the copy
                e.poolMark = g_deferPoolTotal.load(std::memory_order_relaxed);
                e.copy = DeferAlloc(size);
                e.data = data;
                e.size = size;
                memcpy(G2H(e.copy), G2H(data), size);
                // Content hash (not a copy id: the same buffer is also drawn live, and with ids every switch between
                // the copy and the live data re-uploaded it - 28 GB in a minute, Step 35).
                e.hash = XXH3_64bits(G2H(e.copy), size);
                e.rangeNext = 0;
                std::fill(std::begin(e.rangeKey), std::end(e.rangeKey), 0u);
            }
            lastEntry = &e;
            lastCopy = e.copy;
            for (auto& cc : dd.captures) if (cc.header == header) return;
            dd.captures.push_back({ header, e.copy, e.hash, e.size, index ? (i32 ? 2u : 1u) : 0u });
        };
        uint8_t* d8 = G2H<uint8_t>(dev);
        // Vertex range of this draw.
        uint32_t vFirst = 0, vCount = UINT32_MAX;
        if (kind == 0) { vFirst = b; vCount = c; }
        else if (kind == 1)
        {
            const uint32_t ibh = DevU32(d8, DEV_IB);
            uint32_t ibData = 0, ibSize = 0; bool i32 = false;
            if (ibh && bufferOf(ibh, true, ibData, ibSize, i32))
            {
                const uint32_t isz = i32 ? 4 : 2;
                // Capture the index range first: while the copy is reused, the indices of a (start, count) are the
                // ones scanned last time, so its vertex range is reused too (scanning every index of every draw
                // cost ~4% of the render thread, Step 35).
                capture(ibh, true, b * isz, c * isz);
                if (uint64_t(b + c) * isz <= ibSize)
                {
                    uint32_t lo = UINT32_MAX, hi = 0;
                    bool cached = false;
                    const uint32_t key = ((b * 2654435761u) ^ c) | 1u;
                    auto& shard = g_captureShards[(ibh >> 4) & 63];
                    if (lastEntry)
                    {
                        std::lock_guard shardLock(shard.m);
                        if (lastEntry->copy == lastCopy)
                            if (const uint32_t k = (key * 0x9E3779B1u) >> 27; lastEntry->rangeKey[k] == key) { lo = lastEntry->rangeLo[k]; hi = lastEntry->rangeHi[k]; cached = true; }
                    }
                    if (!cached)
                    {
                        // Scan the copy the replay will read (it is immutable), not the live indices.
                        const uint32_t src = lastCopy ? lastCopy : ibData;
                        if (isz == 2) { auto ix = G2H<be<uint16_t>>(src) + b; for (uint32_t k = 0; k < c; k++) { const uint32_t v = ix[k]; if (v == 0xFFFF) continue; lo = std::min(lo, v); hi = std::max(hi, v); } }
                        else { auto ix = G2H<be<uint32_t>>(src) + b; for (uint32_t k = 0; k < c; k++) { const uint32_t v = ix[k]; if (v == 0xFFFFFFFF) continue; lo = std::min(lo, v); hi = std::max(hi, v); } }
                        if (lastEntry)
                        {
                            std::lock_guard shardLock(shard.m);
                            if (lastEntry->copy == lastCopy)
                            {
                                const uint32_t slot = (key * 0x9E3779B1u) >> 27;
                                lastEntry->rangeKey[slot] = key; lastEntry->rangeLo[slot] = lo; lastEntry->rangeHi[slot] = hi;
                            }
                        }
                    }
                    if (lo <= hi && int64_t(lo) + d >= 0) { vFirst = uint32_t(int64_t(lo) + d); vCount = hi - lo + 1; }
                }
            }
        }
        for (uint32_t i = 0; i < 16; i++)
        {
            const uint32_t header = DevU32(d8, DEV_STREAMS + i * 4);
            if (header == 0) continue;
            const uint32_t stride = uint32_t(d8[0x31A0 + i]) * 4;
            const uint32_t fetch0 = DevU32(d8, 0x480 + (95 - i) * 8);
            const uint32_t word6 = G2H<be<uint32_t>>(header)[6];
            uint32_t off = (fetch0 - word6) & 0x1FFFFFFC; if (off >= 0x1000000) off = 0;
            if (vCount == UINT32_MAX || stride == 0) capture(header, false, 0, UINT32_MAX);
            else capture(header, false, off + vFirst * stride, vCount * stride);
        }
    }
    // The device's render states (alpha test / blend / depth ...) as they are now: the job changes them for its
    // next draws, and replaying with the latest ones drew grass and rubble with another draw's alpha-test and
    // blend settings in some frames (they blinked between thin/light and full/dark). FS_NO_DEFER_RS=1: off.
    static const bool s_noRs = getenv("FS_NO_DEFER_RS") != nullptr;
    if (!s_noRs)
    {
        const uint32_t* rs = FindDeviceRsLockFree(dev);
        if (rs == nullptr) rs = RenderStatesFor(dev); // only reached with g_mutex held (see RecordingFastPath)
        dd.renderStates.assign(rs, rs + RS_COUNT);
    }
    const uint32_t rt = DevU32(G2H(dev), DEV_RT), ds = DevU32(G2H(dev), DEV_DS);
    // Test: FS_TEST_CB_START_DELAY_US=<us>: every 29th command buffer starts recording that much later (a job
    // that got the CPU late).
    if (static const int s_delay = [] { const char* e = getenv("FS_TEST_CB_START_DELAY_US"); return e ? atoi(e) : 0; }(); s_delay > 0)
    {
        bool isNew;
        { std::lock_guard recordLock(g_recordMutex); isNew = g_recordingCbs.count(cb) == 0; }
        static std::atomic<uint32_t> s_n{0};
        if (isNew && s_n++ % 29 == 0) std::this_thread::sleep_for(std::chrono::microseconds(s_delay));
    }
    std::lock_guard recordLock(g_recordMutex);
    auto& pcb = g_recordingCbs[cb];
    if (pcb == nullptr)
        pcb = new PendingCommandBuffer();
    pcb->targets.insert(rt);
    pcb->targets.insert(ds);
    if (pcb->draws.empty()) pcb->thread = std::this_thread::get_id();
    else if (pcb->thread != std::this_thread::get_id()) LOG_FIRST(20, "[gpu] note: command buffer 0x{:08X} recorded from two threads", cb);
    dd.frame = g_presentedFrames.load();
    pcb->draws.push_back(std::move(dd));
    return true;
}

// Clears issued on a recording device belong in its command buffer too: run immediately they hit the shared
// target long before the draws they precede (shadow cascades kept the previous cascade's depth / zeros).
static bool DeferClear(uint32_t dev, uint32_t flags, const RenderRect* rect, const float* color, float z, uint32_t stencil)
{
    static const bool s_disabled = getenv("FS_NO_DEFER") != nullptr || getenv("FS_NO_DEFER_CLEAR") != nullptr;
    if (s_disabled || dev == 0 || dev == g_guestDeviceAddress || g_replayOrigin != 0)
        return false;
    const uint32_t cb = DevU32(G2H(dev), 13724);
    if (cb == 0)
        return false;
    DeferredDraw dd{ 3, flags, stencil, uint32_t((color ? 1 : 0) | (rect ? 2 : 0)), 0, DeferAlloc(DEFER_SNAPSHOT_SIZE), dev, 0, 0, {}, {} };
    memcpy(G2H(dd.snapshot), G2H(dev), DEFER_SNAPSHOT_SIZE);
    if (color) for (int i = 0; i < 4; i++) dd.clear[i] = color[i];
    dd.clear[4] = z;
    if (rect) { dd.rect[0] = rect->left; dd.rect[1] = rect->top; dd.rect[2] = rect->right; dd.rect[3] = rect->bottom; }
    const uint32_t rt = DevU32(G2H(dev), DEV_RT), ds = DevU32(G2H(dev), DEV_DS);
    std::lock_guard recordLock(g_recordMutex);
    auto& pcb = g_recordingCbs[cb];
    if (pcb == nullptr)
        pcb = new PendingCommandBuffer();
    pcb->targets.insert(rt);
    pcb->targets.insert(ds);
    if (pcb->draws.empty()) pcb->thread = std::this_thread::get_id();
    else if (pcb->thread != std::this_thread::get_id()) LOG_FIRST(20, "[gpu] note: command buffer 0x{:08X} recorded from two threads", cb);
    dd.frame = g_presentedFrames.load();
    pcb->draws.push_back(std::move(dd));
    return true;
}

static void DrawUpInternal(uint32_t prim, uint32_t count, uint32_t data, uint32_t stride);
static void DoDrawVertices(uint32_t prim, uint32_t start, uint32_t count);
static void DoDrawIndexed(uint32_t prim, int32_t baseVertex, uint32_t startIndex, uint32_t count);
static void TraceEvent(const std::string& what);
static uint64_t g_sceneBatchStrays = 0; // non-scene buffers replayed inside a scene batch (after BeginTiling's clear)
static void ReplayCommandBuffer(PendingCommandBuffer* pcb)
{
    // Step 37 diag: job buffers replayed in a later frame than the one they were recorded in (they missed their
    // resolve), by target, every 600 frames.
    {
        static std::map<std::string, uint64_t> s_late; static uint64_t s_total = 0, s_logAt = 0;
        const uint64_t now = g_presentedFrames.load();
        if (!pcb->draws.empty() && pcb->draws.back().frame < now)
        {
            std::string t; for (auto x : pcb->targets) t += fmt::format("{:08X} ", x);
            s_late[t]++; s_total++;
            static uint32_t s_n = 0;
            if (s_n++ < 40) LOGFN("[late] frame {}: a job buffer of frame {} ({} draws, targets {}) is replayed now", now, pcb->draws.back().frame, pcb->draws.size(), t);
        }
        if (now >= s_logAt + 600)
        {
            s_logAt = now;
            std::string l; for (auto& [t, n] : s_late) l += fmt::format(" [{}x{}]", t, n);
            LOGFN("[late] job buffers replayed a frame late so far: {}{}; non-scene buffers inside a scene batch: {}; captures drawn from upload memory: {}", s_total, l, g_sceneBatchStrays, g_directOnDemand.load());
        }
    }
    if (g_traceFrame && !pcb->draws.empty())
    {
        // Which "view" a command buffer draws: hash of the first draw's VS constants c0-c7 (camera / light matrices).
        auto snap = G2H<uint8_t>(pcb->draws[0].snapshot);
        std::string t; for (auto x : pcb->targets) t += fmt::format(" {:08X}", x);
        auto f = reinterpret_cast<be<float>*>(snap + DEV_VS_CONST);
        std::map<int, int> hist; // log2 of |c0.xyz| (x scale of WorldViewProj) per draw, rounded
        for (auto& dd : pcb->draws)
        {
            auto g = reinterpret_cast<be<float>*>(G2H<uint8_t>(dd.snapshot) + DEV_VS_CONST);
            const float n = std::sqrt(float(g[0]) * float(g[0]) + float(g[1]) * float(g[1]) + float(g[2]) * float(g[2]));
            hist[n > 0 ? int(std::lround(std::log2(n))) : -99]++;
        }
        std::string h; for (auto& [k, v] : hist) h += fmt::format(" {}:{}", k, v);
        if (g_traceFrame) TraceEvent(fmt::format("cb replay {} draws targets{} vsc hash {:016X} c0 ({:.3f} {:.3f} {:.3f} {:.3f}) log2|c0| hist{}", pcb->draws.size(), t,
            XXH3_64bits(snap + DEV_VS_CONST, 8 * 16), float(f[0]), float(f[1]), float(f[2]), float(f[3]), h));
    }
    for (auto& dd : pcb->draws)
    {
        if (dd.poolMark && g_deferPoolTotal.load() - dd.poolMark > DEFER_POOL_SIZE - 0x100000) { g_poolOverwrites++; LOG_FIRST(20, "[gpu] defer pool overwrote a draw still waiting for replay ({} frames old, cb 0x{:08X}) - skipped", g_presentedFrames.load() - dd.frame, pcb->cbObject); continue; }
        if (g_presentedFrames.load() > dd.frame + 8) LOG_FIRST(20, "[gpu] note: replaying a draw recorded {} frames ago (cb 0x{:08X}, {} draws)", g_presentedFrames.load() - dd.frame, pcb->cbObject, pcb->draws.size());
        // FS_TEST_REPLAY_DELAY_US=<n> (tests): burn n microseconds per replayed draw - a render thread as slow as
        // on the tester's real 4K window (10-13 ms per frame), so the job threads record the next frame during the replay.
        {
            static const int s_delayUs = [] { const char* e = getenv("FS_TEST_REPLAY_DELAY_US"); return e ? atoi(e) : 0; }();
            if (s_delayUs > 0)
            {
                const auto until = std::chrono::steady_clock::now() + std::chrono::microseconds(s_delayUs);
                while (std::chrono::steady_clock::now() < until) FS_CPU_PAUSE();
            }
        }
        uint8_t* saved = g_guestDevice;
        g_guestDevice = G2H(dd.snapshot);
        g_replayOrigin = dd.origin;
        g_replayRenderStates = dd.renderStates.empty() ? nullptr : dd.renderStates.data();
        if (dd.kind == 3)
        {
            RenderRect rect(dd.rect[0], dd.rect[1], dd.rect[2], dd.rect[3]);
            ClearInternal(dd.a, (dd.c & 2) ? &rect : nullptr, (dd.c & 1) ? dd.clear : nullptr, dd.clear[4], dd.b);
        }
        else
        {
            // Point captured dynamic buffers at their copy from record time (see DeferDraw).
            // Step 35 (the tester's smeared floor / stair-wall triangles): the game re-points buffer headers at other data
            // between recording and replay. The shadow is brought up to date with the header first; otherwise the
            // header check inside the draw saw the change and re-pointed the shadow at the LIVE data in the middle
            // of the replay (another mesh's vertices, under the capture's hash). The copy's own size goes with it.
            // Step 35m (the tester: garbage polygons after a second level load, about every third run in my test): the
            // game reuses its buffer headers all the time. When a draw's index buffer header had become something
            // else by the time the draw was replayed (another kind of resource, or freed), the header could not be
            // read as an index buffer, the captured copy was not put in place, and the draw went out with the
            // index buffer of the draw before it: the triangle list of another model over this model's vertices
            // (found by tracing all draws of a frame in a good and a bad run: two models drawn with the 5220-byte
            // index buffer of the mesh before them instead of their own 348-byte ones).
            // Now: the copy is used whatever the header is now - through the header's buffer object if there is
            // one (made large enough for the copy, with the copy's size and index width), otherwise through a
            // spare index buffer object; and an indexed draw whose index buffer cannot be resolved is skipped
            // (DoDrawIndexed) instead of drawn with the previous one. FS_OLD_CAPTURE_SWAP=1: as before.
            static const bool s_oldSwap = getenv("FS_OLD_CAPTURE_SWAP") != nullptr;
            static GuestBuffer* s_spareIb = nullptr;
            GuestBuffer* swapped[17]; uint32_t savedData[17], savedSize[17]; RenderFormat savedFormat[17]; size_t nSwapped = 0;
            g_replaySpareIb = false;
            for (auto& c : dd.captures)
            {
                if (nSwapped >= 17) continue;
                const ResourceType type = c.kind == 0 ? ResourceType::VertexBuffer : ResourceType::IndexBuffer;
                auto it = g_shadows.find(c.header);
                if (s_oldSwap && (it == g_shadows.end() || it->second->type != type)) continue;
                auto* old = it != g_shadows.end() && it->second->type == type ? static_cast<GuestBuffer*>(it->second) : nullptr;
                const uint32_t before = old ? old->guestData : 0;
                g_replaySwapLookup = true;
                auto b = static_cast<GuestBuffer*>(GetShadow(c.header, type));
                g_replaySwapLookup = false;
                if (b == nullptr)
                {
                    static std::atomic<uint64_t> s_gone{0};
                    const uint64_t k = ++s_gone;
                    if (k <= 20 || (k & 4095) == 0)
                        LOGFN("[gpu] replay: the header 0x{:08X} of a captured {} buffer is no longer one ({} bytes captured) - {} (#{}, frame {})", c.header, c.kind == 0 ? "vertex" : "index", c.size,
                            c.kind == 0 || s_oldSwap ? "not drawn from" : "the copy is drawn from a spare buffer", k, g_presentedFrames.load());
                    if (c.kind == 0 || s_oldSwap || c.size == 0 || c.size > g_dynamicLimit) continue;
                    if (s_spareIb == nullptr)
                    {
                        s_spareIb = g_userHeap.AllocPhysical<GuestBuffer>(ResourceType::IndexBuffer);
                        s_spareIb->buffer = g_device->createBuffer(RenderBufferDesc::VertexBuffer(AlignUp(g_dynamicLimit, 4), RenderHeapType::DEFAULT, RenderBufferFlag::INDEX));
                        s_spareIb->hostSize = AlignUp(g_dynamicLimit, 4);
                    }
                    b = s_spareIb;
                    b->guestData = c.data;
                    b->dataSize = c.size;
                    b->indexFormat = c.kind == 2 ? RenderFormat::R32_UINT : RenderFormat::R16_UINT;
                    b->hashOverride = c.hash;
                    if (!b->everUploaded || b->uploadedHash != c.hash)
                        UploadShadowBuffer(b);
                    g_indexBuffer = b;
                    g_replaySpareIb = true;
                    continue;
                }
                if (old != nullptr && (b != old || b->guestData != before))
                {
                    static std::atomic<uint64_t> s_repointed{0};
                    if (s_repointed++ < 20)
                        LOGFN("[gpu] replay: buffer header 0x{:08X} was re-pointed since recording (0x{:08X} -> 0x{:08X}, capture 0x{:08X} size 0x{:X})", c.header, before, b->guestData, c.data, c.size);
                }
                swapped[nSwapped] = b; savedData[nSwapped] = b->guestData; savedSize[nSwapped] = b->dataSize; savedFormat[nSwapped] = b->indexFormat; nSwapped++;
                b->liveData = b->guestData;
                b->liveSize = b->dataSize;
                b->guestData = c.data;
                if (s_oldSwap)
                {
                    if (DirectFor(b) && c.size != 0) b->dataSize = c.size; // drawn from upload memory: any size
                }
                else if (c.size != 0)
                {
                    // The copy's own size and index width (the header may describe another buffer by now).
                    if (!DirectFor(b) && AlignUp(c.size, 4) > b->hostSize)
                    {
                        g_pendingBuffers[g_frame].push_back(std::move(b->buffer)); // still used by draws of this frame
                        b->buffer = g_device->createBuffer(RenderBufferDesc::VertexBuffer(AlignUp(c.size, 4), RenderHeapType::DEFAULT, RenderBufferFlag::INDEX));
                        b->hostSize = AlignUp(c.size, 4);
                        b->everUploaded = false;
                        b->uploadedHash = 0;
                        b->shadowDirty = true;
                    }
                    b->dataSize = c.size;
                    if (c.kind != 0) b->indexFormat = c.kind == 2 ? RenderFormat::R32_UINT : RenderFormat::R16_UINT;
                }
                b->hashOverride = c.hash;
            }
            if (dd.kind == 0) DoDrawVertices(dd.a, dd.b, dd.c);
            else if (dd.kind == 1) DoDrawIndexed(dd.a, dd.d, dd.b, dd.c);
            else DrawUpInternal(dd.a, dd.b, dd.data, dd.c);
            // Step 37 test: FS_TEST_SPLIT_AFTER=<n>: while a shadow cascade is replayed, the render pass is ended
            // after the n-th draw of each buffer (what a buffer upload between two draws does) - to force the
            // Odin's checkerboard holes in the shadow maps every frame.
            if (static const int s_split = [] { const char* e = getenv("FS_TEST_SPLIT_AFTER"); return e ? atoi(e) : 0; }(); s_split > 0 && ShadowDiag::curSlot >= 0)
            {
                const size_t idx = size_t(&dd - pcb->draws.data()) + 1;
                if (idx == size_t(s_split) && g_streams[0].buffer && g_streams[0].buffer->buffer)
                    g_commandLists[g_frame]->barriers(RenderBarrierStage::GRAPHICS, RenderBufferBarrier(g_streams[0].buffer->buffer.get(), RenderBufferAccess::READ));
            }
            for (size_t k = 0; k < nSwapped; k++)
            {
                swapped[k]->guestData = savedData[k];
                swapped[k]->dataSize = savedSize[k];
                swapped[k]->indexFormat = savedFormat[k];
                swapped[k]->hashOverride = 0;
            }
            if (g_replaySpareIb)
            {
                g_replaySpareIb = false;
                s_spareIb->hashOverride = 0;
                if (g_indexBuffer == s_spareIb) g_indexBuffer = nullptr;
            }
        }
        g_replayOrigin = 0;
        g_replayRenderStates = nullptr;
        g_guestDevice = saved;
    }
    delete pcb;
}

// Replays ended command buffers in order, up to and including the first one that draws into `target`
// (0: all of them).
static bool g_inTiling = false;
static uint32_t g_tilingRT = 0, g_tilingDS = 0; // targets of the last BeginTiling (its resolves follow EndTiling)
static bool g_sceneResolvedThisFrame = false;   // the tiled scene was resolved (late job buffers then miss it)
static uint64_t g_lateSceneCbs = 0, g_lateSceneFrames = 0;

// all = false: replay up to the FIRST finished command buffer that draws into `target` (one shadow cascade
// per resolve of the shared shadow target). all = true: up to the LAST one - the tiled scene pass is recorded
// by several jobs and the GPU runs all of them before the tile/depth resolves (stopping at the first one
// left most of the scene for after the resolves: the depth texture missed most geometry -> fog everywhere).
static void ReplayEndedCommandBuffers(uint32_t target, bool all = false)
{
    PhaseTimer phase(PH_REPLAY);
    static const bool s_firstOnly = getenv("FS_REPLAY_FIRST_ONLY") != nullptr;
    const bool firstOnly = s_firstOnly || !all;
    std::unique_lock recordLock(g_recordMutex);
    size_t last = SIZE_MAX;
    for (size_t i = 0; i < g_endedCbs.size(); i++)
    {
        const bool hit = target == 0xFFFFFFFF || (target != 0 && g_endedCbs[i]->targets.count(target) != 0);
        if (hit) { last = i; if (firstOnly || target == 0xFFFFFFFF) break; }
    }
    if (last == SIZE_MAX && target != 0)
        return;
    const size_t count = last == SIZE_MAX ? g_endedCbs.size() : last + 1;
    std::vector<PendingCommandBuffer*> batch(g_endedCbs.begin(), g_endedCbs.begin() + count);
    g_endedCbs.erase(g_endedCbs.begin(), g_endedCbs.begin() + count);
    recordLock.unlock();
    // The render jobs finish in a different order every frame. Replaying them in finish order changed the
    // draw order of the main scene from frame to frame, so layered surfaces (rubble decals on the bridge
    // floor) blinked in and out (the tester: "flickering"). Replay a batch in a fixed order instead: by command
    // buffer object, which the game takes from its pool in job order. FS_REPLAY_END_ORDER=1: old order.
    if (all && (target == g_tilingRT || target == g_tilingDS))
        for (auto* p : batch) if (!p->targets.count(g_tilingRT) && !p->targets.count(g_tilingDS)) g_sceneBatchStrays++;
    // Step 38 (GitHub "invisible textures", Poco F5; reproduced on the Odin in the courtyard after the gate: walls,
    // floor and stairs missing, the desert backdrop showing through): some rooms draw part of their level geometry from
    // job buffers that draw into the full-size 1x surfaces (depth at EDRAM 0 = the scene's depth memory, colour at
    // EDRAM 0x2D0). When they finish before the scene is resolved (the phone's timing) the scene batch replays them, and
    // their depth reached the scene (shared host depth) ahead of the scene's own buffers (the PC too, same room). On the console that pass runs before the tiled scene, whose clear wipes its
    // depth; here it was replayed after that clear, so its depth stayed and the scene's walls, floor and stairs
    // (drawn again by the scene's buffers with a strict depth test) failed against it - only the backdrop remained.
    // Such buffers (depth target = the scene's depth memory, not the scene itself) are now replayed without depth
    // writes; their colour goes to their own target as before (the composite later covers it, as on the console).
    // All platforms (the PC showed the same missing walls); FS_SCENE_STRAYS_INLINE=1: old way.
    std::unordered_map<const PendingCommandBuffer*, uint32_t> noZWrite;
    {
        static const bool s_noZ = getenv("FS_SCENE_STRAYS_INLINE") == nullptr; // Step 38: PC too (same bug there)
        if (s_noZ && all && (target == g_tilingRT || target == g_tilingDS) && g_tilingRT && g_tilingDS)
        {
            auto surf = [](uint32_t a) -> GuestSurface* { auto it = g_shadows.find(a); return it != g_shadows.end() && it->second->type == ResourceType::Surface ? static_cast<GuestSurface*>(it->second) : nullptr; };
            GuestSurface* sceneDs = surf(g_tilingDS);
            for (size_t i = 0; i < batch.size(); i++)
            {
                auto* p = batch[i];
                if (p->targets.count(g_tilingRT) || p->targets.count(g_tilingDS) || sceneDs == nullptr)
                    continue;
                uint32_t colour = 0; bool sharesDepth = false;
                for (uint32_t t : p->targets)
                    if (auto* g = surf(t))
                    {
                        if (g->isDepth) sharesDepth |= g->texture == sceneDs->texture;
                        else colour = t;
                    }
                if (sharesDepth && colour != 0)
                {
                    noZWrite[p] = colour;
                    LOG_FIRST(5, "[gpu] scene batch: job buffer with targets 0x{:08X} + the scene's depth memory replayed without depth writes ({} draws)", colour, p->draws.size());
                }
            }
        }
    }
    static const bool s_endOrder = getenv("FS_REPLAY_END_ORDER") != nullptr;
    if (all && !s_endOrder && batch.size() > 1)
    {
        std::stable_sort(batch.begin(), batch.end(), [](const PendingCommandBuffer* a, const PendingCommandBuffer* b) { return a->cbObject < b->cbObject; });
        // The objects come from a ring: if the batch wrapped around, start after the biggest address gap.
        size_t start = 0; uint32_t gap = 0;
        for (size_t i = 0; i < batch.size(); i++)
        {
            const uint32_t next = batch[(i + 1) % batch.size()]->cbObject, cur = batch[i]->cbObject;
            const uint32_t g = i + 1 < batch.size() ? next - cur : cur - next; // wrap gap measured backwards
            if (i + 1 < batch.size() && g > gap) { gap = g; start = i + 1; }
        }
        if (gap > 0x4000) // normal spacing is 0xD0 per object
            std::rotate(batch.begin(), batch.begin() + start, batch.end());
    }
    for (size_t i = 0; i < batch.size(); i++)
    {
        PendingCommandBuffer* pcb = batch[i];
        const auto rd = noZWrite.find(pcb);
        const uint32_t from = rd != noZWrite.end() ? rd->second : 0;
        if (g_traceFrame) TraceEvent(fmt::format("cb order: cb 0x{:08X} dev 0x{:08X} {} draws{}", pcb->cbObject, pcb->device, pcb->draws.size(), from ? " (no depth writes)" : ""));
        g_replayNoZWrite = from != 0;
        ReplayCommandBuffer(pcb);
        g_replayNoZWrite = false;
    }
}

// Shadow cascades: the game renders every cascade into one 1024x1024 target and resolves each into its slot
// of a 4096x1024 atlas (dst x = 1024 * cascade), in whatever order the jobs finish. Each job's command
// buffer draws one cascade; tell them apart by the x scale of WorldViewProj (|c0.xyz|): about 4x per cascade
// (log2 classes like -8, -6, -4, -2 for atlas slots 0..3; slot 0 is the farthest cascade).
static float CommandBufferScale(const PendingCommandBuffer* pcb)
{
    std::vector<float> v;
    for (auto& dd : pcb->draws)
    {
        auto g = reinterpret_cast<be<float>*>(G2H<uint8_t>(dd.snapshot) + DEV_VS_CONST);
        const float n = std::sqrt(float(g[0]) * float(g[0]) + float(g[1]) * float(g[1]) + float(g[2]) * float(g[2]));
        if (n > 1e-6f && std::isfinite(n)) v.push_back(std::log2(n));
    }
    if (v.empty()) return NAN;
    std::nth_element(v.begin(), v.begin() + v.size() / 2, v.end());
    return v[v.size() / 2];
}

struct CascadeCentre { float value; uint64_t lastFrame; };
static std::map<uint32_t, std::vector<CascadeCentre>> g_cascadeCentres; // guarded by g_recordMutex

// Step 35j (the tester: "the rectangle shadow is moving alongside the camera"): the atlas slot of a cascade used to be
// its RANK among the scales seen lately. In his courtyard the 16-64 m cascade has no casters, so only three
// scales exist (-7.66, -4.01, -2.01) and the two near cascades landed one slot too low: every receiver looked
// its shadow up in the wrong cascade's map. The scales follow the cascades' far ranges (200 / 64 / 16 / 4 m:
// log2 = -7.64 / -6 / -4 / -2), so a scale now names its slot by itself. Only when a scale fits none of them
// (another set of ranges) the rank is used as before. FS_CASCADE_RANK=1: always the rank.
static uint32_t CascadeSlotOf(const std::vector<CascadeCentre>& centres, size_t k)
{
    static const bool s_rank = getenv("FS_CASCADE_RANK") != nullptr;
    static const float anchors[4] = { -7.64f, -6.0f, -4.0f, -2.0f };
    auto anchorOf = [](float x) { int best = 0; for (int a = 1; a < 4; a++) if (std::fabs(anchors[a] - x) < std::fabs(anchors[best] - x)) best = a; return best; };
    if (s_rank)
        return uint32_t(k);
    // Step 35k: a scale that is off the known ones (seen for a moment after a new game: -4.71, -9.98) no longer
    // switches everything back to ranks (that brought the wrong-slot shadows back for the 120 frames the stray
    // scale was remembered): it simply goes to the nearest cascade.
    if (std::fabs(anchors[anchorOf(centres[k].value)] - centres[k].value) > 0.7f)
        LOG_FIRST(5, "[gpu] note: shadow cascade scale {:.2f} is off the known ones - nearest slot {}", centres[k].value, anchorOf(centres[k].value));
    return uint32_t(anchorOf(centres[k].value));
}

// Step 35j (the tester's capture: far shadows gone for single frames, 9 times in 4 s): is the command buffer of this
// atlas slot's cascade among the finished ones? `expected`: that cascade was drawn within the last 3 frames.
// Call with g_recordMutex held.
// Step 37 (the tester, Odin: sunlit patches - light through a lattice, a patch of sand - flashing for single frames where a
// building's shadow should be): a cascade can come in several command buffers (the job threads split the casters);
// the wait below took the first one as "arrived" and the slot was drawn without the others' casters. Each slot now
// remembers how many buffers it had last time, and the wait is for that many. FS_CASCADE_COUNT_OFF=1: old.
struct SlotCount { uint32_t count = 0; uint64_t frame = 0; };
static std::map<std::pair<uint32_t, uint32_t>, SlotCount> g_slotBufCount; // guarded by g_recordMutex
static uint64_t g_slotHist[4] = {}, g_slotPartial = 0, g_lateCascadeParts = 0;
static std::map<std::pair<uint32_t, uint32_t>, uint64_t> g_slotReplayedFrame; // guarded by g_recordMutex
static bool CascadeBuffersSeenOne(const PendingCommandBuffer* p, uint32_t target, uint32_t slot, const std::vector<CascadeCentre>& centres)
{
    const float x = CommandBufferScale(p);
    if (std::isnan(x)) return false;
    size_t best = SIZE_MAX;
    for (size_t k = 0; k < centres.size(); k++)
        if (std::fabs(centres[k].value - x) < 1.0f && (best == SIZE_MAX || std::fabs(centres[k].value - x) < std::fabs(centres[best].value - x))) best = k;
    return best != SIZE_MAX && CascadeSlotOf(centres, best) == slot;
}
static uint32_t CascadeBuffersSeen(uint32_t target, uint32_t slot, const std::vector<CascadeCentre>& centres)
{
    uint32_t n = 0;
    for (auto* p : g_endedCbs)
    {
        if (!p->targets.count(target)) continue;
        const float x = CommandBufferScale(p);
        if (std::isnan(x)) continue;
        size_t best = SIZE_MAX;
        for (size_t k = 0; k < centres.size(); k++)
            if (std::fabs(centres[k].value - x) < 1.0f && (best == SIZE_MAX || std::fabs(centres[k].value - x) < std::fabs(centres[best].value - x))) best = k;
        if (best != SIZE_MAX && CascadeSlotOf(centres, best) == slot) n++;
    }
    return n;
}

static bool CascadeArrived(uint32_t target, uint32_t slot, bool& expected)
{
    static const bool s_countOff = getenv("FS_CASCADE_COUNT") == nullptr; // opt-in: on the Odin route no part came late (0 in 2 runs) and the wait cost 21 stalls of 12 ms
    if (!s_countOff)
    {
        expected = false;
        auto it = g_cascadeCentres.find(target);
        if (it == g_cascadeCentres.end())
            return false;
        auto& centres = it->second;
        for (size_t k = 0; k < centres.size(); k++)
            if (CascadeSlotOf(centres, k) == slot && g_presentedFrames.load() - centres[k].lastFrame <= 3) expected = true;
        if (!expected)
            return false;
        uint32_t want = 1;
        if (auto c = g_slotBufCount.find({ target, slot }); c != g_slotBufCount.end() && g_presentedFrames.load() - c->second.frame <= 3)
            want = std::max<uint32_t>(1, c->second.count);
        return CascadeBuffersSeen(target, slot, centres) >= want;
    }
    expected = false;
    auto it = g_cascadeCentres.find(target);
    if (it == g_cascadeCentres.end())
        return false;
    auto& centres = it->second;
    for (size_t k = 0; k < centres.size(); k++)
        if (CascadeSlotOf(centres, k) == slot && g_presentedFrames.load() - centres[k].lastFrame <= 3) expected = true;
    if (!expected)
        return false;
    for (auto* p : g_endedCbs)
    {
        if (!p->targets.count(target)) continue;
        const float x = CommandBufferScale(p);
        if (std::isnan(x)) continue;
        size_t best = SIZE_MAX;
        for (size_t k = 0; k < centres.size(); k++)
            if (std::fabs(centres[k].value - x) < 1.0f && (best == SIZE_MAX || std::fabs(centres[k].value - x) < std::fabs(centres[best].value - x))) best = k;
        if (best != SIZE_MAX && CascadeSlotOf(centres, best) == slot) return true;
    }
    return false;
}

uint32_t g_atlasTexHeaderForShots = 0;
static uint32_t g_atlasTexHeader = 0; // the texture the shadow cascades are resolved into (set by the resolve hook)
static void ReplayAtlasSlot(uint32_t target, uint32_t slot)
{
    PhaseTimer phase(PH_REPLAY);
    std::vector<PendingCommandBuffer*> toReplay; // replayed after g_recordMutex is released
    std::unique_lock recordLock(g_recordMutex);
    // Learned cascade scales per target (log2 |c0|). Slot order = ascending scale: the pixel shaders' cascade
    // constants put the FAR cascade (64-200 m, smallest scale) in slot 0 and the nearest (0-4 m) in slot 3. A command buffer belongs to
    // the closest centre within 1.0 (cascades are ~2.0 apart); centres unused for 120 frames are dropped.
    using Centre = CascadeCentre;
    auto& centres = g_cascadeCentres[target];
    const uint64_t frame = g_presentedFrames.load();
    std::erase_if(centres, [&](const Centre& c) { return frame - c.lastFrame > 120; });
    auto nearest = [&](float x) -> Centre* { Centre* best = nullptr; for (auto& c : centres) if (std::fabs(c.value - x) < 1.0f && (!best || std::fabs(c.value - x) < std::fabs(best->value - x))) best = &c; return best; };
    for (auto* p : g_endedCbs)
        if (p->targets.count(target))
            if (float x = CommandBufferScale(p); !std::isnan(x))
            {
                if (Centre* c = nearest(x)) { c->value = c->value * 0.8f + x * 0.2f; c->lastFrame = frame; }
                else centres.push_back({ x, frame });
            }
    // Debug: FS_LOG_CASCADES=2: every 300th frame, the finished shadow command buffers each atlas resolve finds
    // (scale, draws into the shadow target, all draws).
    if (static const bool s_detail = [] { const char* e = getenv("FS_LOG_CASCADES"); return e && atoi(e) >= 2; }(); s_detail && frame % 300 < 2)
    {
        std::string list;
        for (auto* p : g_endedCbs)
        {
            size_t shadowDraws = 0;
            for (auto& dd : p->draws) { uint8_t* snap = G2H<uint8_t>(dd.snapshot); if (DevU32(snap, DEV_RT) == target || DevU32(snap, DEV_DS) == target) shadowDraws++; }
            list += fmt::format(" [{}scale {:.2f}, {} shadow draws of {}]", p->targets.count(target) ? "" : "other, ", CommandBufferScale(p), shadowDraws, p->draws.size());
        }
        size_t recording = 0; for (auto& [cb, p] : g_recordingCbs) if (p->targets.count(target)) recording++;
        LOGFN("[gpu] cascade detail frame {} slot {}: {} finished buffers{}; {} still recording into the shadow target", frame, slot, g_endedCbs.size(), list, recording);
    }
    static const bool s_desc = getenv("FS_CASCADE_DESC") != nullptr; // debug: reverse the slot order
    std::sort(centres.begin(), centres.end(), [](const Centre& a, const Centre& b) { return s_desc ? a.value > b.value : a.value < b.value; });
    {
        // Step 37: how many command buffers this slot's cascade came in (see CascadeArrived).
        const uint32_t n = CascadeBuffersSeen(target, slot, centres);
        g_slotReplayedFrame[{ target, slot }] = frame;
        auto& sc = g_slotBufCount[{ target, slot }];
        if (n > 0)
        {
            if (sc.frame + 3 >= frame && n < sc.count) g_slotPartial++;
            g_slotHist[std::min<uint32_t>(n, 3)]++;
            // a larger count is kept for a while, a smaller one only replaces it when seen twice in a row
            static std::map<std::pair<uint32_t, uint32_t>, uint32_t> s_lower;
            if (n >= sc.count || sc.frame + 3 < frame) { sc.count = n; s_lower[{ target, slot }] = 0; }
            else if (++s_lower[{ target, slot }] >= 2) { sc.count = n; s_lower[{ target, slot }] = 0; }
            sc.frame = frame;
        }
        static uint64_t s_log = 0;
        if (frame >= s_log + 600) { s_log = frame; LOGFN("[gpu] cascade buffers per slot: 1 x{}, 2 x{}, 3+ x{}; fewer than last time {}; parts that came after their slot was drawn {}", g_slotHist[1], g_slotHist[2], g_slotHist[3], g_slotPartial, g_lateCascadeParts); }
    }
    // Command buffers that finished before and do not draw into the shadow target run first, in order (the
    // depth pre-pass): left queued, they ran after BeginTiling's clear and their depth hid the bridge.
    // Step 37 (the tester, Odin: sunlight flashing for single frames where a building's shadow should be): a job of the
    // lit scene that finished before the shadow atlas was complete was replayed right here, between two cascade
    // resolves - its surfaces were lit from an atlas that did not have this frame's cascades yet. (It needs fast
    // job threads: seen with the Odin's lock-free recording, never on the PC.) Buffers that draw into the tiled
    // scene's colour target now stay queued for the scene; the depth pre-pass (no colour target of the scene) still
    // runs here. FS_EARLY_SCENE_REPLAY=1: as before.
    static const bool s_earlyScene = getenv("FS_KEEP_EARLY_SCENE") == nullptr; // opt-in to keep them: it never happened (0 scene buffers early in every run), so the old behaviour stays
    static uint64_t s_kept = 0, s_ran = 0, s_keptFrames = 0, s_lastKeptFrame = ~0ull, s_logAt = 0;
    for (size_t i = 0; i < g_endedCbs.size();)
    {
        PendingCommandBuffer* p = g_endedCbs[i];
        if (!p->targets.count(target))
        {
            bool scene = g_tilingRT != 0 && p->targets.count(g_tilingRT) != 0;
            // ...or any buffer whose draws sample the shadow atlas itself
            size_t atlasDraws = 0;
            if (g_atlasTexHeader != 0)
                for (auto& dd : p->draws)
                {
                    if (dd.kind == 3) continue;
                    uint8_t* snap = G2H<uint8_t>(dd.snapshot);
                    for (uint32_t t = 0; t < 16; t++) if (DevU32(snap, DEV_TEXTURES + t * 4) == g_atlasTexHeader) { atlasDraws++; break; }
                }
            if (static const bool s_logEarly = getenv("FS_LOG_EARLY") != nullptr; s_logEarly && frame > 3200 && frame % 97 < 2)
            {
                std::string t; for (auto x : p->targets) t += fmt::format(" {:08X}", x);
                uint8_t* snap0 = p->draws.empty() ? nullptr : G2H<uint8_t>(p->draws[0].snapshot);
                std::string tx; if (snap0) for (uint32_t k = 0; k < 8; k++) tx += fmt::format(" {:08X}", uint32_t(DevU32(snap0, DEV_TEXTURES + k * 4)));
                LOGFN("[early] frame {} slot {}: buffer 0x{:08X} targets{} draws {} (sampling the atlas 0x{:08X}: {}) tiling rt 0x{:08X} ds 0x{:08X} | first draw textures{}", frame, slot, p->cbObject, t, p->draws.size(), g_atlasTexHeader, atlasDraws, g_tilingRT, g_tilingDS, tx);
            }
            if (atlasDraws != 0) scene = true;
            if (scene) { s_kept++; if (s_lastKeptFrame != frame) { s_lastKeptFrame = frame; s_keptFrames++; } }
            else s_ran++;
            if (scene && !s_earlyScene) { i++; continue; }
            g_endedCbs.erase(g_endedCbs.begin() + i);
            toReplay.push_back(p);
            continue;
        }
        i++;
    }
    if (frame >= s_logAt + 600) { s_logAt = frame; LOGFN("[gpu] job buffers finished before the shadow atlas: {} scene buffers in {} frames ({}), {} others run early", s_kept, s_keptFrames, s_earlyScene ? "run early" : "kept for the scene", s_ran); }
    for (size_t i = 0; i < g_endedCbs.size();)
    {
        PendingCommandBuffer* p = g_endedCbs[i];
        if (p->targets.count(target))
        {
            // A job's command buffer can hold more than its shadow cascade (e.g. main-scene draws too): replay
            // only the draws into the shadow target now and leave the rest for the scene. Replaying the whole
            // buffer here drew the bridge into the main target before the scene's clear (bridge vanished).
            PendingCommandBuffer* shadowPart = new PendingCommandBuffer();
            std::vector<bool> isShadow(p->draws.size(), false);
            for (size_t k = 0; k < p->draws.size(); k++)
            {
                uint8_t* snap = G2H<uint8_t>(p->draws[k].snapshot);
                const uint32_t rt = DevU32(snap, DEV_RT), ds = DevU32(snap, DEV_DS);
                isShadow[k] = rt == target || ds == target;
                if (isShadow[k]) shadowPart->draws.push_back(p->draws[k]);
            }
            const float x = shadowPart->draws.empty() ? NAN : CommandBufferScale(shadowPart);
            Centre* c = std::isnan(x) ? nullptr : nearest(x);
            if (c && CascadeSlotOf(centres, size_t(c - centres.data())) == slot)
            {
                shadowPart->targets = p->targets;
                shadowPart->cbObject = p->cbObject;
                shadowPart->device = p->device;
                std::vector<DeferredDraw> rest;
                for (size_t k = 0; k < p->draws.size(); k++)
                    if (!isShadow[k]) rest.push_back(std::move(p->draws[k]));
                p->draws = std::move(rest);
                if (p->draws.empty())
                {
                    g_endedCbs.erase(g_endedCbs.begin() + i);
                    delete p;
                }
                else
                {
                    p->targets.erase(target);
                    i++;
                }
                toReplay.push_back(shadowPart); // deleted by ReplayCommandBuffer
                continue;
            }
            delete shadowPart;
        }
        i++;
    }
    // Step 37 diag: the state the big tower mesh (stream 0 of 136164 bytes at the tester's lattice wall) is drawn with into
    // each cascade - logged whenever it differs from the last time for that slot. FS_LOG_TOWER=1.
    if (static const bool s_tower = getenv("FS_LOG_TOWER") != nullptr; s_tower)
    {
        static std::map<uint32_t, std::string> s_lastSig; static uint32_t s_lines = 0;
        for (auto* p : toReplay)
        {
            if (!p->targets.count(target)) continue;
            for (size_t k = 0; k < p->draws.size(); k++)
            {
                auto& dd = p->draws[k];
                if (dd.kind == 3) continue;
                uint8_t* snap = G2H<uint8_t>(dd.snapshot);
                const uint32_t header = DevU32(snap, DEV_STREAMS);
                if (header == 0) continue;
                const uint32_t size = ((uint32_t(G2H<be<uint32_t>>(header)[7]) >> 2) & 0xFFFFFF) * 4;
                if (size != 136164) continue;
                auto rsv = [&](uint32_t i) { return dd.renderStates.size() > i ? dd.renderStates.data()[i] : 0xDEADu; };
                std::string consts; { auto g = reinterpret_cast<be<float>*>(snap + DEV_VS_CONST); for (int q = 0; q < 16; q++) consts += fmt::format(" {:.3f}", float(g[q])); }
                const std::string sig = fmt::format("cc {:08X} dc {:08X} cull {:08X} mask {:X} blend {:08X} | rs: at {} ref {} func {} z {} zw {} zf {} cullrs {} bias {:08X} slope {:08X} cw {:X} | tex0 {:08X} vs {:08X} ps {:08X}",
                    uint32_t(DevU32(snap, 10556)), uint32_t(DevU32(snap, 10548)), uint32_t(DevU32(snap, 10568)), uint32_t(DevU32(snap, 12036)) & 0xF, uint32_t(DevU32(snap, 12028)),
                    rsv(RS_ALPHATESTENABLE), rsv(RS_ALPHAREF), rsv(RS_ALPHAFUNC), rsv(RS_ZENABLE), rsv(RS_ZWRITEENABLE), rsv(RS_ZFUNC), rsv(RS_CULLMODE), rsv(RS_DEPTHBIAS), rsv(RS_DEPTHBIAS - 1), rsv(RS_COLORWRITEENABLE),
                    uint32_t(DevU32(snap, DEV_TEXTURES)), uint32_t(DevU32(snap, DEV_VS)), uint32_t(DevU32(snap, DEV_PS)));
                std::string c2; { auto g = reinterpret_cast<be<float>*>(snap + DEV_VS_CONST); for (int q = 0; q < 16; q++) c2 += fmt::format(" {:.2f}", float(g[q])); }
                const std::string full = sig.substr(0, sig.find("| tex0")) + c2;
                if (frame > 3000 && s_lastSig[slot] != full && s_lines < 3000)
                {
                    s_lines++;
                    LOGFN("[tower] frame {} slot {} draw {}/{}: {} | c0-c3{}", frame, slot, k, p->draws.size(), sig, consts);
                    s_lastSig[slot] = full;
                }
            }
        }
    }
    // Step 37 diag (the tester's Odin: sunlit patches flashing for single frames): a slot whose shadow draw count jumps
    // from the frames around it is logged (draws into the shadow target replayed for this slot now vs last time).
    {
        size_t shadowDraws = 0;
        for (auto* p : toReplay) if (p->targets.count(target)) for (auto& dd : p->draws) { uint8_t* snap = G2H<uint8_t>(dd.snapshot); if (DevU32(snap, DEV_RT) == target || DevU32(snap, DEV_DS) == target) shadowDraws++; }
        static std::map<std::pair<uint32_t, uint32_t>, size_t> s_last;
        size_t& last = s_last[{ target, slot }];
        static uint32_t s_logged = 0;
        const size_t diff = shadowDraws > last ? shadowDraws - last : last - shadowDraws;
        static const bool s_logJumps = getenv("FS_LOG_SHADOW_JUMPS") != nullptr;
        if (s_logJumps && last != 0 && diff > std::max<size_t>(3, last / 8) && s_logged < 3000)
        {
            s_logged++;
            LOGFN("[shadowjump] frame {} slot {}: {} shadow draws (last time {}), {} buffers, {} still recording", frame, slot, shadowDraws, last, toReplay.size(), [&] { size_t r = 0; for (auto& [cb, p] : g_recordingCbs) if (p->targets.count(target)) r++; return r; }());
        }
        last = shadowDraws;
    }
    recordLock.unlock();
    ShadowDiag::curSlot = int(slot);
    for (auto* p : toReplay)
        ReplayCommandBuffer(p);
    ShadowDiag::curSlot = -1;
}

static void EndDeferredCommandBuffer(uint32_t dev)
{
    const uint32_t cb = DevU32(G2H(dev), 13724);
    std::lock_guard recordLock(g_recordMutex);
    auto it = g_recordingCbs.find(cb);
    if (it == g_recordingCbs.end())
        return;
    it->second->cbObject = cb;
    it->second->device = dev;
    if (!it->second->draws.empty() && it->second->thread != std::this_thread::get_id()) LOG_FIRST(20, "[gpu] note: command buffer 0x{:08X} ended on another thread than it was recorded", cb);
    if (g_sceneResolvedThisFrame && (it->second->targets.count(g_tilingRT) || it->second->targets.count(g_tilingDS)))
    {
        static uint64_t s_lastFrame = ~0ull;
        g_lateSceneCbs++;
        if (s_lastFrame != g_presentedFrames.load()) { s_lastFrame = g_presentedFrames.load(); g_lateSceneFrames++; }
        LOG_FIRST(20, "[gpu] LATE job command buffer 0x{:08X} ({} draws) ended after the scene was resolved (frame {})", cb, it->second->draws.size(), g_presentedFrames.load());
    }
    for (auto& [key, f] : g_slotReplayedFrame)
        if (f == g_presentedFrames.load() && it->second->targets.count(key.first))
            if (auto c = g_cascadeCentres.find(key.first); c != g_cascadeCentres.end())
                if (CascadeBuffersSeenOne(it->second, key.first, key.second, c->second)) { g_lateCascadeParts++; break; }
    g_endedCbs.push_back(it->second);
    g_recordingCbs.erase(it);
    g_recordCv.notify_all();
}

// Debug: FS_TRACE_FRAME=<s> logs the order of clears, resolves and draws (device, target) of one frame.
static std::string g_traceLast;
static int g_traceRepeat = 0;
static void TraceEvent(const std::string& what)
{
    if (!g_traceFrame) return;
    if (what == g_traceLast) { g_traceRepeat++; return; }
    if (!g_traceLast.empty()) LOGFN("[trace] {} x{}", g_traceLast, g_traceRepeat + 1);
    g_traceLast = what; g_traceRepeat = 0;
}
static void TraceFrameBoundary()
{
    static const double s_time = [] { const char* e = getenv("FS_TRACE_FRAME"); return e ? atof(e) : -1.0; }();
    static const auto s_start = std::chrono::steady_clock::now();
    static int s_state = 0; // 0 before, 1 tracing, 2 done
    if (s_time < 0 || s_state == 2) return;
    // FS_TRACE_FRAMES=<n>: trace n consecutive frames (default 1).
    static int s_left = [] { const char* e = getenv("FS_TRACE_FRAMES"); return e ? std::max(1, atoi(e)) : 1; }();
    if (s_state == 1)
    {
        TraceEvent("<present>"); TraceEvent("");
        if (--s_left > 0) { LOGFN("[trace] frame start"); return; }
        g_traceFrame = false; s_state = 2; return;
    }
    if (std::chrono::duration<double>(std::chrono::steady_clock::now() - s_start).count() >= s_time) { s_state = 1; g_traceFrame = true; LOGFN("[trace] frame start"); }
}
// Forgotten Sands records most of its 3D draws on other device objects (one per render job, same layout as
// the main device; the main device later runs their command buffers). We draw them immediately, reading
// the state from the device the draw was issued on.
